"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[73074],{28453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>r});var i=a(96540);const n={},o=i.createContext(n);function s(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),i.createElement(o.Provider,{value:t},e.children)}},46520:(e,t,a)=>{a.d(t,{A:()=>i});const i=a.p+"assets/images/OCC-91d80dc77e9585e8811d80913d368a72.png"},52990:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/07/17/what-is-acid-on-a-data-lake","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-07-17-what-is-acid-on-a-data-lake.md","source":"@site/blog/2026-07-17-what-is-acid-on-a-data-lake.md","title":"What is ACID on a Data Lake?","description":"What ACID means for tables on S3, GCS or ADLS: how table formats like Apache Hudi deliver atomic commits, snapshot isolation and safe concurrent writes.","date":"2026-07-17T00:00:00.000Z","tags":[{"inline":true,"label":"acid","permalink":"/blog/tags/acid"},{"inline":true,"label":"concurrency control","permalink":"/blog/tags/concurrency-control"},{"inline":true,"label":"hudi timeline","permalink":"/blog/tags/hudi-timeline"},{"inline":true,"label":"data lakehouse","permalink":"/blog/tags/data-lakehouse"}],"readingTime":13.4,"hasTruncateMarker":false,"authors":[{"name":"Sivabalan Narayanan","url":"https://www.linkedin.com/in/sivabalan-narayanan-1040b45/","imageURL":"/assets/images/authors/sivabalan.jpg","key":"sivabalan","page":null}],"frontMatter":{"title":"What is ACID on a Data Lake?","excerpt":"What atomicity, consistency, isolation and durability actually mean for tables on object storage, and how lakehouse table formats like Apache Hudi deliver them.","description":"What ACID means for tables on S3, GCS or ADLS: how table formats like Apache Hudi deliver atomic commits, snapshot isolation and safe concurrent writes.","authors":["sivabalan"],"category":"how-to","image":"/assets/images/blog/acid.png","tags":["acid","concurrency control","hudi timeline","data lakehouse"]},"unlisted":false,"lastUpdatedAt":1784061194000,"nextItem":{"title":"What is Incremental ETL on a Data Lake?","permalink":"/blog/2026/07/16/what-is-incremental-etl-on-a-data-lake"}}')},57050:(e,t,a)=>{a.d(t,{A:()=>i});const i=a.p+"assets/images/hudi-timeline-actions-e56d0d9fad5645d9910f2591ad7775de.png"},85272:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>i,toc:()=>c});var i=a(52990),n=a(74848),o=a(28453);const s={title:"What is ACID on a Data Lake?",excerpt:"What atomicity, consistency, isolation and durability actually mean for tables on object storage, and how lakehouse table formats like Apache Hudi deliver them.",description:"What ACID means for tables on S3, GCS or ADLS: how table formats like Apache Hudi deliver atomic commits, snapshot isolation and safe concurrent writes.",authors:["sivabalan"],category:"how-to",image:"/assets/images/blog/acid.png",tags:["acid","concurrency control","hudi timeline","data lakehouse"]},r=void 0,l={authorsImageUrls:[void 0]},c=[{value:"What A, C, I and D Mean on Object Storage",id:"what-a-c-i-and-d-mean-on-object-storage",level:2},{value:"Life Before ACID on Data Lakes",id:"life-before-acid-on-data-lakes",level:2},{value:"How Table Formats Deliver ACID",id:"how-table-formats-deliver-acid",level:2},{value:"Concurrency Control Models",id:"concurrency-control-models",level:2},{value:"What ACID on a Data Lake Does Not Mean",id:"what-acid-on-a-data-lake-does-not-mean",level:2},{value:"Why It Matters",id:"why-it-matters",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function d(e){const t={a:"a",code:"code",em:"em",h2:"h2",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components},{PostFAQ:i}=t;return i||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:'ACID on a data lake means that writes to tables stored on object storage are Atomic, Consistent, Isolated and Durable \u2014 the same transactional guarantees a database provides, applied to files in S3, GCS or ADLS. That sentence is easy to say and surprisingly hard to deliver. A database owns its storage engine end to end; a data lake is a pile of Parquet files on an object store that offers durable single-object PUTs and nothing more. There is no multi-file atomic operation, no rename that atomically swaps a directory of files, and no built-in notion of "these 500 files belong to one write." Without extra machinery, a reader can list a directory while a writer is halfway through it and see a partial write, and two jobs writing to the same partition can silently clobber each other\'s output. ACID on a lake is the machinery \u2014 a commit protocol layered over the object store \u2014 that closes those gaps.'}),"\n",(0,n.jsxs)(t.p,{children:["This post walks through what each of the four letters means concretely at the file level, how lakes worked before table formats existed, how formats like ",(0,n.jsx)(t.a,{href:"https://hudi.apache.org",children:"Apache Hudi"})," deliver these guarantees, and \u2014 just as important \u2014 what ACID on a lake does ",(0,n.jsx)(t.em,{children:"not"})," promise."]}),"\n",(0,n.jsx)(t.h2,{id:"what-a-c-i-and-d-mean-on-object-storage",children:"What A, C, I and D Mean on Object Storage"}),"\n",(0,n.jsx)(t.p,{children:"The textbook definitions of ACID were written for databases processing many small transactions. On a data lake, the transactions are large batch or streaming writes that produce files, so it is worth restating each property in file terms."}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Atomicity"})," means a write either publishes completely or not at all. Consider a Spark job writing 500 Parquet files into a table and dying at file 320 \u2014 an executor is lost, a spot instance is reclaimed, someone kills the job. Atomicity requires that those 320 orphaned files are never visible to any query, and that the failed write can be cleanly rolled back. Without it, every downstream consumer inherits a partially written dataset and no reliable way to detect it."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Consistency"})," means every write moves the table from one valid state to another valid state. On a lake this covers schema enforcement (a write with an incompatible schema is rejected rather than quietly producing unreadable files), key constraints like upsert semantics (a record with the same key updates in place rather than duplicating), and the invariant that the table's metadata always describes exactly the set of files that constitute the table."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Isolation"})," means concurrent readers and writers do not observe each other's intermediate states. Two failure modes matter here. First, two writers targeting the same partition at the same time \u2014 say, a backfill job and a streaming ingest job \u2014 must not interleave their files such that the table ends up with a mix of both writes' partial output. Second, a reader that starts listing files mid-write must not see half of a commit; it should see the table exactly as it was at some committed point, even if the query runs for an hour while new commits land."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Durability"})," means a committed write survives failures. Object stores already provide excellent durability for individual objects \u2014 S3, GCS and ADLS replicate objects across zones. The lake-specific part of durability is that the ",(0,n.jsx)(t.em,{children:"commit record itself"}),' is persisted to the same durable storage, so that "was this write committed?" has a crash-proof answer, and a committed transaction is never silently rolled back by a subsequent cleanup process.']}),"\n",(0,n.jsx)(t.h2,{id:"life-before-acid-on-data-lakes",children:"Life Before ACID on Data Lakes"}),"\n",(0,n.jsx)(t.p,{children:"The Hadoop and early cloud-lake era answered these problems with conventions, not guarantees. It is worth remembering how fragile those conventions were, because they explain why table formats exist."}),"\n",(0,n.jsxs)(t.p,{children:["The classic Hive pattern was the ",(0,n.jsx)(t.strong,{children:"partition swap"}),': write data into a staging directory, then "atomically" move it into place and update the Hive metastore partition location. On HDFS a directory rename was genuinely atomic, so this mostly worked. On object stores there are no directories and no atomic rename \u2014 a "rename" is a copy-then-delete of every object \u2014 so the same pattern became a slow, non-atomic window during which readers could see anything.']}),"\n",(0,n.jsxs)(t.p,{children:["The ",(0,n.jsxs)(t.strong,{children:[(0,n.jsx)(t.code,{children:"_SUCCESS"})," file"]})," convention had MapReduce and Spark drop an empty marker file when a job finished, and downstream jobs would poll for it. This signaled completion but protected nothing: readers that listed the directory directly saw partial data, a rerun of a failed job could mix old and new files, and there was no rollback story at all \u2014 cleanup after a failed job meant a human with a delete command deciding which files were orphans."]}),"\n",(0,n.jsxs)(t.p,{children:["Layered on top of this, early S3 offered only ",(0,n.jsx)(t.strong,{children:"eventual consistency"})," for listings, so even a fully written directory might not be fully ",(0,n.jsx)(t.em,{children:"visible"})," yet. Whole projects (S3Guard, committers with DynamoDB bookkeeping) existed just to paper over that. S3 became strongly consistent in 2020, which removed one class of bugs \u2014 but strong single-object consistency still does not give you multi-file atomicity, isolation between writers, or rollback. Those require a transaction log."]}),"\n",(0,n.jsx)(t.h2,{id:"how-table-formats-deliver-acid",children:"How Table Formats Deliver ACID"}),"\n",(0,n.jsxs)(t.p,{children:["The shared insight behind Apache Hudi, Apache Iceberg and Delta Lake is that the table's state should be defined by a ",(0,n.jsx)(t.strong,{children:"metadata log with an atomic publish step"}),", not by whatever files happen to be in a directory. Data files are written first, invisibly; then a single, small metadata operation makes them visible all at once. Because that final operation is one atomic object-store action (a single PUT, or a conditional/compare-and-swap write), the entire multi-file write inherits its atomicity."]}),"\n",(0,n.jsxs)(t.p,{children:["In Hudi, that log is the ",(0,n.jsx)(t.a,{href:"/docs/timeline",children:"timeline"})," \u2014 an ordered event log of every action performed on the table, stored under the table's ",(0,n.jsx)(t.code,{children:".hoodie/timeline"})," directory. Each write is an action that moves through explicit states: ",(0,n.jsx)(t.code,{children:"REQUESTED"})," (the write is planned), ",(0,n.jsx)(t.code,{children:"INFLIGHT"})," (data files are being produced), and ",(0,n.jsx)(t.code,{children:"COMPLETED"})," (the write is published). The transition to ",(0,n.jsx)(t.code,{children:"COMPLETED"})," is a single atomic object-store operation, and Hudi timestamps every action with monotonically increasing, ",(0,n.jsx)(t.a,{href:"/docs/timeline#truetime-generation",children:"TrueTime"}),"-style instants so actions are globally ordered even across independent processes."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.img,{alt:"Actions in the Hudi timeline",src:a(57050).A+"",width:"817",height:"424"}),"\n",(0,n.jsx)("p",{align:"center",children:"Figure: Writes and table services recorded as actions on the Hudi timeline"})]}),"\n",(0,n.jsx)(t.p,{children:"This structure delivers each letter directly:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Atomicity"}),": our 500-file Spark job that dies at file 320 leaves an ",(0,n.jsx)(t.code,{children:"INFLIGHT"})," action on the timeline and 320 uncommitted files that no query will ever read, because queries resolve visible files through completed timeline actions \u2014 never by listing directories. A rollback action later removes the orphaned files. Nothing partial is ever served."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Consistency"}),": the timeline is the single source of truth for table state, and schema and key constraints are enforced as part of the write before the commit is published."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Isolation"}),": readers get ",(0,n.jsx)(t.strong,{children:"snapshot isolation"}),". A query binds to the set of completed commits as of its start and sees exactly that state for its entire duration, no matter how many writes complete concurrently. Multi-version concurrency control (MVCC) keeps prior file versions around so long-running queries are never yanked out from under."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Durability"}),": the commit metadata lives on the same replicated object storage as the data, so a completed instant is as durable as the data it describes."]}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:["For a deeper walkthrough of how the timeline underpins each transaction state transition, see the earlier post ",(0,n.jsx)(t.a,{href:"/blog/2023/07/09/Hoodie-Timeline-Foundational-pillar-for-ACID-transactions",children:"Hoodie Timeline: Foundational pillar for ACID transactions"}),"."]}),"\n",(0,n.jsxs)(t.p,{children:["To be fair to the broader ecosystem: Apache Iceberg and Delta Lake achieve ACID through the same fundamental idea with different mechanics. Iceberg builds immutable snapshot trees of manifest files and commits by atomically swapping a pointer to the new table metadata (typically via a catalog's compare-and-swap). Delta Lake maintains a JSON transaction log (",(0,n.jsx)(t.code,{children:"_delta_log"}),") where writing log entry ",(0,n.jsx)(t.em,{children:"N+1"})," is the atomic commit point, using conditional writes on the object store. All three give you atomic multi-file commits and snapshot isolation; they differ in how metadata is organized, how conflicts are detected, and what concurrency patterns they optimize for. This transactional layer is a defining ingredient of the ",(0,n.jsx)(t.a,{href:"/blog/2024/07/11/what-is-a-data-lakehouse",children:"lakehouse architecture"})," generally, not a Hudi-only concept."]}),"\n",(0,n.jsx)(t.h2,{id:"concurrency-control-models",children:"Concurrency Control Models"}),"\n",(0,n.jsxs)(t.p,{children:["Atomic commits solve the single-writer case. The harder question \u2014 and where table formats differ most \u2014 is what happens when multiple processes write to the same table. Hudi's ",(0,n.jsx)(t.a,{href:"/docs/concurrency_control",children:"concurrency control"})," documentation lays out a spectrum of models:"]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Single writer with table services."})," Most pipelines have one writer, plus background table services (compaction, clustering, cleaning) that rewrite data for performance. Hudi distinguishes these by design: table services run lock-free alongside the writer, coordinated through the timeline via MVCC, either inline or fully async in the same process. For this very common case, no external lock infrastructure is needed at all."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Optimistic concurrency control (OCC)."})," When genuinely separate jobs write to one table \u2014 a streaming ingest plus a batch backfill, say \u2014 Hudi supports OCC at file-group granularity. Each writer proceeds without blocking, and at commit time takes a short-lived distributed lock to check whether a concurrently completed commit touched the same files. Non-overlapping writes both succeed; overlapping writes cause one to abort and retry. The lock is held only around the commit-time critical section, not for the duration of the job."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.img,{alt:"Optimistic concurrency control",src:a(46520).A+"",width:"2014",height:"700"}),"\n",(0,n.jsx)("p",{align:"center",children:"Figure: Optimistic concurrency control \u2014 conflicts detected at commit time"})]}),"\n",(0,n.jsx)(t.p,{children:"OCC works well when conflicts are rare, but it has an honest weakness for streaming: two high-frequency writers that routinely touch the same file groups will repeatedly abort each other, wasting compute and starving progress."}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Non-blocking concurrency control (NBCC)."})," For multi-writer streaming, Hudi supports a mode where multiple writers can write into the ",(0,n.jsx)(t.em,{children:"same"})," file groups simultaneously without aborting each other. Instead of preventing the conflict, resolution is deferred: commits are ordered by completion time on the timeline, and the query reader and the compactor merge overlapping writes deterministically. A lock is needed only for the instant-metadata write to the timeline itself. NBCC currently targets merge-on-read tables with bucket indexes, and reflects a streaming-native view of concurrency: serialize the log, not the writers."]}),"\n",(0,n.jsx)(t.h2,{id:"what-acid-on-a-data-lake-does-not-mean",children:"What ACID on a Data Lake Does Not Mean"}),"\n",(0,n.jsx)(t.p,{children:'Honesty matters here, because "ACID" invites comparisons to OLTP databases that lakes are not designed to win.'}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"It is not OLTP."})," Commit latency on a lakehouse is measured in seconds \u2014 an object-store round trip plus metadata work \u2014 not the milliseconds of a transactional database. Lakehouse transactions are designed for batches and micro-batches of records, not single-row point writes at high QPS."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Transactions span one table."})," The unit of atomicity in Hudi (and its peers, by and large) is a single table's commit. Multi-table transactions, cross-table foreign keys, and interactive multi-statement transactions with ",(0,n.jsx)(t.code,{children:"BEGIN"}),"/",(0,n.jsx)(t.code,{children:"COMMIT"})," semantics are not part of the model."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Isolation is snapshot isolation, not serializability of arbitrary read-write transactions."})," Writers are serialized against each other per table, and readers see consistent snapshots \u2014 which is exactly what analytical workloads need \u2014 but you should not port an OLTP application's locking assumptions onto a lake."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"ACID does not fix bad pipelines."})," Atomic commits guarantee that what was written is either fully visible or invisible; they do not validate that the data itself was correct."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"If your workload is high-QPS point reads and writes, use an operational database and land the changes onto the lake via CDC \u2014 which, conveniently, is a workload where lake ACID shines."}),"\n",(0,n.jsx)(t.h2,{id:"why-it-matters",children:"Why It Matters"}),"\n",(0,n.jsx)(t.p,{children:"These guarantees are not academic; they are what make several load-bearing patterns possible at all."}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"CDC correctness."})," Replicating a database table into the lake via change data capture means a continuous stream of upserts and deletes. Without atomic commits and key-based upserts, a mid-batch failure leaves the lake copy in a state the source database never had \u2014 and there is no way to reconcile. With ACID, every commit is an all-or-nothing application of a batch of changes, and incremental consumers downstream see change batches in a well-defined order, never partially."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Concurrent ingestion and table services."})," Real tables need continuous compaction, clustering and cleaning to stay queryable. Running those alongside ingestion without transactions means either stopping the world or risking corruption. MVCC on the timeline lets Hudi rewrite data in the background while writers write and readers read, with each process pinned to a consistent snapshot."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Regulatory deletes."})," GDPR and CCPA erasure requests require deleting specific records from immutable files \u2014 physically, a read-modify-rewrite of affected files. ACID makes each deletion pass atomic and auditable: the timeline records exactly when the delete committed, queries never see a half-deleted state, and the commit history serves as evidence of compliance."]}),"\n",(0,n.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,n.jsxs)(t.p,{children:["ACID on a data lake is a commit protocol over object storage: data files are written invisibly, then published through one atomic metadata operation, with snapshot isolation for readers and explicit concurrency control between writers. Hudi implements this with its ",(0,n.jsx)(t.a,{href:"/docs/timeline",children:"timeline"})," \u2014 an ordered, durable event log of every action on the table \u2014 plus a spectrum of ",(0,n.jsx)(t.a,{href:"/docs/concurrency_control",children:"concurrency control"})," modes ranging from lock-free single-writer deployments to OCC and non-blocking multi-writer streaming. Iceberg and Delta Lake deliver the same core guarantees through their own log designs. None of this turns a lake into an OLTP database, and it should not be sold that way; what it does is make tables on cheap object storage trustworthy enough to run CDC pipelines, concurrent services and compliance workloads that raw file lakes could never support. That trust is the foundation the rest of the lakehouse stack is built on."]}),"\n",(0,n.jsx)(t.h2,{id:"faq",children:"FAQ"}),"\n",(0,n.jsx)(i,{heading:null,items:[{question:"Does S3 support ACID transactions?",answer:"Not by itself. S3 provides durable, strongly consistent operations on individual objects, but no atomic operation spanning multiple objects and no isolation between concurrent writers. ACID transactions on S3 come from a table format layered on top, such as Apache Hudi, Apache Iceberg or Delta Lake, which publishes multi-file writes through a single atomic metadata commit."},{question:"Is a data lake ACID compliant?",answer:"A raw data lake of Parquet or ORC files is not ACID compliant: readers can observe partial writes, concurrent jobs can corrupt each other, and failed jobs leave orphaned files. A data lake becomes ACID compliant when tables are managed by a transactional table format, at which point it is usually called a lakehouse."},{question:"How does Hudi guarantee atomicity?",answer:"Hudi records every write as an action on its timeline, moving through requested, inflight and completed states. Data files are written first but remain invisible; the transition to completed is a single atomic object-store operation. Queries only read files referenced by completed actions, so a failed write is never visible and is later rolled back cleanly."},{question:"What is snapshot isolation on a data lake?",answer:"Snapshot isolation means every query reads the table as of a specific committed state and sees exactly that state for its entire run, even while new writes commit concurrently. Table formats implement it with multi-version concurrency control, keeping prior file versions available until no reader needs them."},{question:"Can multiple jobs write to the same lakehouse table at once?",answer:"Yes, with concurrency control. Hudi supports optimistic concurrency control, where writers proceed in parallel and conflicts on overlapping files are detected at commit time using a short-lived lock, and non-blocking concurrency control, where multiple writers can even target the same file group and conflicts are resolved at read and compaction time."},{question:"Is ACID on a data lake the same as ACID in a database like PostgreSQL?",answer:"The guarantees are the same in kind but different in scope and latency. Lakehouse transactions cover batches of records within one table and commit in seconds, whereas an OLTP database offers millisecond, multi-statement, often multi-table transactions. Lakes are built for analytical and streaming workloads, not high-QPS point reads and writes."}]})]})}function h(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);